mapper.select:
SELECT J.JOB_ID AS job_id, J.JOB_NAME AS job_name, J.TASK_KEY AS task_key, J.ENABLED_YN AS enabled_yn, J.TIMEZONE AS timezone, TO_CHAR(J.MAX_RUNTIME_SEC) AS max_runtime_sec, J.ALLOW_MANUAL_RUN_YN AS allow_manual_run_yn, J.DESCRIPTION AS description, NVL(R.RUNNING_YN, 'N') AS running_yn, NVL(R.STOP_REQUEST_YN, 'N') AS stop_request_yn, TO_CHAR(S.SCHEDULE_ID) AS schedule_id, S.SCHEDULE_TYPE AS schedule_type, S.CRON_EXPR AS cron_expr, TO_CHAR(S.INTERVAL_SEC) AS interval_sec, S.ENABLED_YN AS schedule_enabled_yn, TO_CHAR(S.NEXT_RUN_AT, 'YYYY-MM-DD HH24:MI:SS') AS next_run_at, TO_CHAR(J.LAST_START_AT, 'YYYY-MM-DD HH24:MI:SS') AS last_start_at, TO_CHAR(J.LAST_END_AT, 'YYYY-MM-DD HH24:MI:SS') AS last_end_at, J.LAST_RESULT_CODE AS last_result_code, J.LAST_RESULT_MSG AS last_result_msg, TO_CHAR(J.MOD_DT, 'YYYY-MM-DD HH24:MI:SS') AS mod_dt FROM TB_STK_BATCH_JOB_DEF J LEFT JOIN TB_STK_BATCH_JOB_SCHEDULE S ON S.JOB_ID = J.JOB_ID LEFT JOIN TB_STK_BATCH_JOB_RUNTIME R ON R.JOB_ID = J.JOB_ID WHERE 1=1
AND UPPER(J.JOB_ID) LIKE '%' || UPPER(#{in_job_id}) || '%'
AND J.TASK_KEY = #{in_task_key}
AND J.ENABLED_YN = #{in_enabled_yn}
AND NVL(R.RUNNING_YN, 'N') = #{in_running_yn}
AND NVL(J.LAST_RESULT_CODE, '') = #{in_result_code}
ORDER BY J.JOB_ID

SELECT * FROM ( SELECT EXEC_ID AS exec_id, BATCH_ID AS batch_id, TO_CHAR(BASE_DT, 'YYYY-MM-DD') AS base_dt, STATUS AS status, TO_CHAR(TOTAL_CNT) AS total_cnt, TO_CHAR(SUCCESS_CNT) AS success_cnt, TO_CHAR(FAIL_CNT) AS fail_cnt, TO_CHAR(START_AT, 'YYYY-MM-DD HH24:MI:SS') AS start_at, TO_CHAR(END_AT, 'YYYY-MM-DD HH24:MI:SS') AS end_at, ERROR_MSG AS error_msg FROM TB_BATCH_EXEC_LOG WHERE ( BATCH_ID = #{job_id}
OR BATCH_ID LIKE 'BATCH_' || REPLACE(UPPER(#{task_key}), '_RUN', '') || '_%'
)
AND INSTR(UPPER(BATCH_ID), '_' || UPPER(#{market_group}) || '_') > 0
AND BASE_DT = TO_DATE(#{base_dt}, 'YYYY-MM-DD')
ORDER BY START_AT DESC ) WHERE ROWNUM <= 200

SELECT * FROM ( SELECT EXEC_ID AS exec_id, BATCH_ID AS batch_id, TO_CHAR(BASE_DT, 'YYYY-MM-DD') AS base_dt, MKT_CD AS mkt_cd, STK_CD AS stk_cd, STK_NM AS stk_nm, ITEM_STATUS AS item_status, ERROR_MSG AS error_msg, TO_CHAR(CREATED_AT, 'YYYY-MM-DD HH24:MI:SS') AS created_at FROM TB_BATCH_EXEC_ITEM_LOG WHERE ITEM_STATUS = 'FAIL' AND ( BATCH_ID = #{job_id}
OR BATCH_ID LIKE 'BATCH_' || REPLACE(UPPER(#{task_key}), '_RUN', '') || '_%'
)
AND UPPER(MKT_CD) = UPPER(#{market_group})
ORDER BY CREATED_AT DESC ) WHERE ROWNUM <= 500

mapper.update:
UPDATE TB_STK_BATCH_JOB_DEF
   SET JOB_NAME = #{job_name}
     , TASK_KEY = #{task_key}
     , ENABLED_YN = #{enabled_yn}
     , TIMEZONE = #{timezone}
     , MAX_RUNTIME_SEC = TO_NUMBER(#{max_runtime_sec})
     , ALLOW_MANUAL_RUN_YN = #{allow_manual_run_yn}
     , DESCRIPTION = #{description}
     , MOD_DT = SYSDATE
 WHERE JOB_ID = #{job_id}

UPDATE TB_STK_BATCH_JOB_RUNTIME
   SET RUNNING_YN = 'Y'
     , LOCK_OWNER = #{lock_owner}
     , LOCK_AT = SYSDATE
     , LAST_HEARTBEAT_AT = SYSDATE
     , STOP_REQUEST_YN = 'N'
     , CURRENT_EXEC_ID = #{exec_id}
     , MOD_DT = SYSDATE
 WHERE JOB_ID = #{job_id}
   AND RUNNING_YN = 'N'

mapper.select:
SELECT STOP_REQUEST_YN
  FROM TB_STK_BATCH_JOB_RUNTIME
 WHERE JOB_ID = #{job_id}

mapper.update:
UPDATE TB_STK_BATCH_JOB_DEF
   SET LAST_END_AT = SYSDATE
     , LAST_RESULT_CODE = #{last_result_code}
     , LAST_RESULT_MSG = #{last_result_msg}
     , MOD_DT = SYSDATE
 WHERE JOB_ID = #{job_id}
